<title>Game of Life — Interactive Explorer</title>
<style>
  * { box-sizing: border-box; margin: 0; padding: 0; }
  body {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    background: #0f1117;
    color: #e0e0e0;
    min-height: 100vh;
    padding: 20px;
  }
  .container { max-width: 1200px; margin: 0 auto; }
  h1 {
    font-size: 24px;
    font-weight: 600;
    margin-bottom: 8px;
    background: linear-gradient(135deg, #6ee7b7, #60a5fa);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
  }
  .subtitle { color: #9ca3af; margin-bottom: 20px; font-size: 14px; }
  .main { display: flex; gap: 20px; flex-wrap: wrap; }
  .canvas-wrap {
    flex: 1;
    min-width: 400px;
    background: #1a1d29;
    border-radius: 12px;
    padding: 16px;
    border: 1px solid #2a2d3a;
  }
  #canvas {
    display: block;
    background: #0a0c12;
    border-radius: 8px;
    cursor: crosshair;
    width: 100%;
    image-rendering: pixelated;
  }
  .controls {
    width: 280px;
    display: flex;
    flex-direction: column;
    gap: 16px;
  }
  .panel {
    background: #1a1d29;
    border-radius: 12px;
    padding: 16px;
    border: 1px solid #2a2d3a;
  }
  .panel h3 {
    font-size: 13px;
    text-transform: uppercase;
    letter-spacing: 0.5px;
    color: #9ca3af;
    margin-bottom: 12px;
    font-weight: 600;
  }
  .btn-row { display: flex; gap: 8px; flex-wrap: wrap; }
  button {
    padding: 8px 14px;
    border: 1px solid #3a3d4a;
    border-radius: 6px;
    background: #252836;
    color: #e0e0e0;
    cursor: pointer;
    font-size: 13px;
    transition: all 0.15s;
  }
  button:hover { background: #303446; border-color: #4a4d5a; }
  button.primary {
    background: linear-gradient(135deg, #3b82f6, #2563eb);
    border-color: #3b82f6;
    color: white;
  }
  button.primary:hover {
    background: linear-gradient(135deg, #60a5fa, #3b82f6);
  }
  button.danger {
    background: #dc2626;
    border-color: #dc2626;
    color: white;
  }
  button.danger:hover { background: #ef4444; }
  select, input[type="range"] {
    width: 100%;
    padding: 6px 8px;
    background: #252836;
    border: 1px solid #3a3d4a;
    border-radius: 6px;
    color: #e0e0e0;
    font-size: 13px;
  }
  .stat-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 8px;
  }
  .stat {
    background: #252836;
    padding: 10px;
    border-radius: 6px;
