        <div class="slider-row" style="margin-top: 12px;">
          <label>Speed <span class="speed-display" id="speedVal">10 fps</span></label>
          <input type="range" id="speedSlider" min="1" max="60" value="10">
        </div>
        <div class="slider-row">
          <label>Grid size <span class="speed-display" id="sizeVal">60 × 40</span></label>
          <input type="range" id="sizeSlider" min="20" max="120" value="60">
        </div>
      </div>

      <div class="panel">
        <h3>Rule</h3>
        <select id="ruleSelect">
          <option value="conway">Conway's Game of Life (B3/S23)</option>
          <option value="highlife">HighLife (B36/S23)</option>
          <option value="daynight">Day &amp; Night (B3678/S34678)</option>
          <option value="seeds">Seeds (B2/S)</option>
          <option value="maze">Maze (B3/S12345)</option>
          <option value="2x2">2x2 (B36/S125)</option>
          <option value="replicator">Replicator (B1357/S1357)</option>
          <option value="livefreeordie">Live Free or Die (B2/S0)</option>
        </select>
      </div>

      <div class="panel">
        <h3>Patterns</h3>
        <div class="pattern-grid">
          <button class="pattern-btn" data-pattern="glider">Glider</button>
          <button class="pattern-btn" data-pattern="blinker">Blinker</button>
          <button class="pattern-btn" data-pattern="toad">Toad</button>
          <button class="pattern-btn" data-pattern="beacon">Beacon</button>
          <button class="pattern-btn" data-pattern="pulsar">Pulsar</button>
          <button class="pattern-btn" data-pattern="gliderGun">Gosper Gun</button>
          <button class="pattern-btn" data-pattern="block">Block</button>
          <button class="pattern-btn" data-pattern="beehive">Beehive</button>
        </div>
        <div style="margin-top: 10px;">
          <button id="randomBtn" style="width: 100%;">🎲 Randomize (30%)</button>
        </div>
      </div>

      <div class="panel">
        <h3>Statistics</h3>
        <div class="stat-grid">
          <div class="stat">
            <div class="stat-label">Generation</div>
            <div class="stat-value" id="genVal">0</div>
