            <div class="stat-label">Alive</div>
            <div class="stat-value" id="aliveVal">0</div>
          </div>
          <div class="stat">
            <div class="stat-label">Density</div>
            <div class="stat-value" id="densityVal">0%</div>
          </div>
          <div class="stat">
            <div class="stat-label">Peak</div>
            <div class="stat-value" id="peakVal">0</div>
