  </div>
</div>

<script>
// ── Rule definitions ────────────────────────────────────────────────────────
const RULES = {
  conway:     { birth: [3], survival: [2, 3] },
  highlife:   { birth: [3, 6], survival: [2, 3] },
  daynight:   { birth: [3, 6, 7, 8], survival: [3, 4, 6, 7, 8] },
  seeds:      { birth: [2], survival: [] },
  maze:       { birth: [3], survival: [1, 2, 3, 4, 5] },
  "2x2":      { birth: [3, 6], survival: [1, 2, 5] },
  replicator: { birth: [1, 3, 5, 7], survival: [1, 3, 5, 7] },
  livefreeordie: { birth: [2], survival: [0] },
};

// ── Pattern library (relative coordinates) ──────────────────────────────────
const PATTERNS = {
  glider: [[0,0],[1,1],[2,1],[0,2],[1,2]],
  blinker: [[0,0],[1,0],[2,0]],
  toad: [[1,0],[2,0],[3,0],[0,1],[1,1],[2,1]],
  beacon: [[0,0],[1,0],[0,1],[3,2],[2,3],[3,3]],
  pulsar: [
    [2,0],[3,0],[4,0],[8,0],[9,0],[10,0],
    [0,2],[5,2],[7,2],[12,2],
    [0,3],[5,3],[7,3],[12,3],
    [0,4],[5,4],[7,4],[12,4],
    [2,5],[3,5],[4,5],[8,5],[9,5],[10,5],
    [2,7],[3,7],[4,7],[8,7],[9,7],[10,7],
    [0,8],[5,8],[7,8],[12,8],
    [0,9],[5,9],[7,9],[12,9],
    [0,10],[5,10],[7,10],[12,10],
    [2,12],[3,12],[4,12],[8,12],[9,12],[10,12],
  ],
  gliderGun: [
    [24,0],[22,1],[24,1],[12,2],[13,2],[20,2],[21,2],[34,2],[35,2],
    [11,3],[15,3],[20,3],[21,3],[34,3],[35,3],[0,4],[1,4],[10,4],
    [16,4],[20,4],[21,4],[0,5],[1,5],[10,5],[14,5],[16,5],[17,5],
    [22,5],[24,5],[10,6],[16,6],[24,6],[11,7],[15,7],[12,8],[13,8],
  ],
  block: [[0,0],[1,0],[0,1],[1,1]],
  beehive: [[1,0],[2,0],[0,1],[3,1],[1,2],[2,2]],
};

// ── State ───────────────────────────────────────────────────────────────────
const canvas = document.getElementById('canvas');
const ctx = canvas.getContext('2d');
let cols = 60, rows = 40;
let grid = [];
let running = false;
let generation = 0;
let peakAlive = 0;
let speed = 10;
let currentRule = 'conway';
let animationId = null;
let lastStep = 0;
let drawing = false;
let drawValue = true;
let placePattern = null;

// ── Grid operations ─────────────────────────────────────────────────────────
function createGrid() {
  grid = new Array(rows);
  for (let y = 0; y < rows; y++) {
    grid[y] = new Array(cols).fill(false);
  }
}

function getCell(x, y) {
  return grid[((y % rows) + rows) % rows][((x % cols) + cols) % cols];
}

function setCell(x, y, val) {
  grid[((y % rows) + rows) % rows][((x % cols) + cols) % cols] = val;
}

function countNeighbors(x, y) {
  let count = 0;
  for (let dy = -1; dy <= 1; dy++) {
    for (let dx = -1; dx <= 1; dx++) {
      if (dx === 0 && dy === 0) continue;
      if (getCell(x + dx, y + dy)) count++;
    }
  }
  return count;
}

function step() {
  const rule = RULES[currentRule];
  const birthSet = new Set(rule.birth);
  const surviveSet = new Set(rule.survival);
  const newGrid = new Array(rows);

  for (let y = 0; y < rows; y++) {
    newGrid[y] = new Array(cols);
    for (let x = 0; x < cols; x++) {
      const n = countNeighbors(x, y);
      const alive = getCell(x, y);
      if (alive && surviveSet.has(n)) {
        newGrid[y][x] = true;
      } else if (!alive && birthSet.has(n)) {
        newGrid[y][x] = true;
      } else {
        newGrid[y][x] = false;
      }
    }
  }
  grid = newGrid;
  generation++;
  updateStats();
}

function countAlive() {
  let count = 0;
  for (let y = 0; y < rows; y++) {
    for (let x = 0; x < cols; x++) {
      if (grid[y][x]) count++;
    }
  }
  return count;
}

// ── Rendering ───────────────────────────────────────────────────────────────
function resizeCanvas() {
  const cellW = canvas.width / cols;
  const cellH = canvas.height / rows;
  return { cellW, cellH };
}

function draw() {
  const { cellW, cellH } = resizeCanvas();
  ctx.fillStyle = '#0a0c12';
  ctx.fillRect(0, 0, canvas.width, canvas.height);

  // Draw cells
  ctx.fillStyle = '#6ee7b7';
  for (let y = 0; y < rows; y++) {
    for (let x = 0; x < cols; x++) {
      if (grid[y][x]) {
        ctx.fillRect(x * cellW, y * cellH, cellW - 0.5, cellH - 0.5);
      }
    }
  }

  // Draw pattern preview
  if (placePattern && mouseCell) {
    ctx.fillStyle = 'rgba(96, 165, 250, 0.5)';
    const pat = PATTERNS[placePattern];
    if (pat) {
      for (const [dx, dy] of pat) {
        const px = mouseCell.x + dx;
        const py = mouseCell.y + dy;
        if (px >= 0 && px < cols && py >= 0 && py < rows) {
          ctx.fillRect(px * cellW, py * cellH, cellW - 0.5, cellH - 0.5);
        }
      }
    }
  }

  // Grid lines (subtle)
  if (cols <= 80) {
    ctx.strokeStyle = 'rgba(255,255,255,0.03)';
    ctx.lineWidth = 0.5;
    for (let x = 0; x <= cols; x++) {
      ctx.beginPath();
      ctx.moveTo(x * cellW, 0);
      ctx.lineTo(x * cellW, canvas.height);
      ctx.stroke();
    }
    for (let y = 0; y <= rows; y++) {
      ctx.beginPath();
      ctx.moveTo(0, y * cellH);
      ctx.lineTo(canvas.width, y * cellH);
      ctx.stroke();
    }
  }
}

// ── Animation loop ──────────────────────────────────────────────────────────
function animate(timestamp) {
  if (running) {
    const interval = 1000 / speed;
    if (timestamp - lastStep >= interval) {
      step();
      lastStep = timestamp;
    }
  }
  draw();
  animationId = requestAnimationFrame(animate);
}

// ── Stats ───────────────────────────────────────────────────────────────────
function updateStats() {
  const alive = countAlive();
  if (alive > peakAlive) peakAlive = alive;
  const density = (alive / (cols * rows) * 100).toFixed(1);
  document.getElementById('genVal').textContent = generation;
  document.getElementById('aliveVal').textContent = alive;
  document.getElementById('densityVal').textContent = density + '%';
  document.getElementById('peakVal').textContent = peakAlive;
}

// ── Mouse interaction ───────────────────────────────────────────────────────
let mouseCell = null;

function getMousePos(e) {
  const rect = canvas.getBoundingClientRect();
  const cellW = canvas.width / cols;
  const cellH = canvas.height / rows;
  const x = Math.floor((e.clientX - rect.left) / cellW);
  const y = Math.floor((e.clientY - rect.top) / cellH);
  return { x, y };
}

canvas.addEventListener('mousedown', (e) => {
  const pos = getMousePos(e);
  if (placePattern) {
    const pat = PATTERNS[placePattern];
    if (pat) {
      for (const [dx, dy] of pat) {
        setCell(pos.x + dx, pos.y + dy, true);
      }
      placePattern = null;
      updateStats();
      return;
    }
  }
  drawing = true;
  drawValue = !getCell(pos.x, pos.y);
  setCell(pos.x, pos.y, drawValue);
  updateStats();
});

canvas.addEventListener('mousemove', (e) => {
  mouseCell = getMousePos(e);
  if (drawing && !placePattern) {
    setCell(mouseCell.x, mouseCell.y, drawValue);
    updateStats();
  }
});

canvas.addEventListener('mouseup', () => { drawing = false; });
canvas.addEventListener('mouseleave', () => { drawing = false; mouseCell = null; });

// ── Controls ────────────────────────────────────────────────────────────────
document.getElementById('playBtn').addEventListener('click', () => {
  running = !running;
  document.getElementById('playBtn').textContent = running ? '⏸ Pause' : '▶ Play';
});

document.getElementById('stepBtn').addEventListener('click', () => {
  step();
});

document.getElementById('clearBtn').addEventListener('click', () => {
  createGrid();
  generation = 0;
  peakAlive = 0;
  updateStats();
});

document.getElementById('randomBtn').addEventListener('click', () => {
  createGrid();
  for (let y = 0; y < rows; y++) {
    for (let x = 0; x < cols; x++) {
      grid[y][x] = Math.random() < 0.3;
    }
  }
  generation = 0;
  peakAlive = 0;
  updateStats();
});

document.getElementById('speedSlider').addEventListener('input', (e) => {
  speed = parseInt(e.target.value);
  document.getElementById('speedVal').textContent = speed + ' fps';
});

document.getElementById('sizeSlider').addEventListener('input', (e) => {
  cols = parseInt(e.target.value);
  rows = Math.floor(cols * 0.66);
  document.getElementById('sizeVal').textContent = cols + ' × ' + rows;
  createGrid();
  generation = 0;
  peakAlive = 0;
  updateStats();
});

document.getElementById('ruleSelect').addEventListener('change', (e) => {
  currentRule = e.target.value;
  generation = 0;
  peakAlive = countAlive();
});

// Pattern buttons
document.querySelectorAll('.pattern-btn').forEach(btn => {
  btn.addEventListener('click', () => {
    placePattern = btn.dataset.pattern;
    running = false;
    document.getElementById('playBtn').textContent = '▶ Play';
  });
});

// ── Init ────────────────────────────────────────────────────────────────────
createGrid();
updateStats();
animate(0);
</script>
</body>
</html>
