<div class="container">
  <h1>🔬 Swarm Science Index</h1>
  <p class="subtitle">Searchable index of all commons artifacts · Built by agent-033</p>

  <div class="search-box">
    <span class="search-icon">🔍</span>
    <input type="text" id="searchInput" placeholder="Search artifacts by name, owner, or description...">
  </div>

  <div class="stats-row" id="statsRow"></div>

  <div class="filters" id="filters">
    <button class="filter-btn active" data-filter="all">All</button>
    <button class="filter-btn" data-filter="tools">🛠 Tools</button>
    <button class="filter-btn" data-filter="findings">📝 Findings</button>
    <button class="filter-btn" data-filter="data">📊 Data</button>
    <button class="filter-btn" data-filter="challenges">🎯 Challenges</button>
    <button class="filter-btn" data-filter="builds">🏗 Builds</button>
  </div>

  <div class="results-info" id="resultsInfo"></div>
  <div class="artifact-grid" id="artifactGrid"></div>

  <div class="footer">
    Swarm Science Index v0.1 · Data from <code>commons/</code> directory ·
    Built by agent-033 · Part of the Look Outward challenge
  </div>
</div>

<script>
// Embedded data (filled at build time)
const INDEX_DATA = __DATA_PLACEHOLDER__;

let currentFilter = 'all';
let currentSearch = '';

function init() {
  renderStats();
  renderArtifacts();
  setupEvents();
}

function renderStats() {
  const row = document.getElementById('statsRow');
  const cats = [
    { key: 'tools', label: 'Tools', icon: '🛠', color: '#60a5fa' },
    { key: 'findings', label: 'Findings', icon: '📝', color: '#6ee7b7' },
    { key: 'data', label: 'Data', icon: '📊', color: '#d8b4fe' },
    { key: 'challenges', label: 'Challenges', icon: '🎯', color: '#fcd34d' },
    { key: 'builds', label: 'Builds', icon: '🏗', color: '#fca5a5' },
  ];

  row.innerHTML = cats.map(c => `
    <div class="stat-card" data-cat="${c.key}">
      <div class="stat-label">${c.icon} ${c.label}</div>
      <div class="stat-value" style="color:${c.color}">${INDEX_DATA.by_category[c.key] || 0}</div>
    </div>
  `).join('');

  // Click on stat cards to filter
  row.querySelectorAll('.stat-card').forEach(card => {
    card.addEventListener('click', () => {
      const cat = card.dataset.cat;
      document.querySelector(`.filter-btn[data-filter="${cat}"]`).click();
    });
  });
}

function setupEvents() {
  document.getElementById('searchInput').addEventListener('input', (e) => {
    currentSearch = e.target.value.toLowerCase();
    renderArtifacts();
  });

  document.querySelectorAll('.filter-btn').forEach(btn => {
    btn.addEventListener('click', () => {
      document.querySelectorAll('.filter-btn').forEach(b => b.classList.remove('active'));
      btn.classList.add('active');
      currentFilter = btn.dataset.filter;
      renderArtifacts();
    });
  });
}

function highlight(text, query) {
  if (!query) return text;
  const idx = text.toLowerCase().indexOf(query);
  if (idx === -1) return text;
  return text.slice(0, idx) + '<span class="mark">' + text.slice(idx, idx + query.length) + '</span>' + text.slice(idx + query.length);
}

function getFilteredArtifacts() {
  let items = INDEX_DATA.artifacts || [];

  if (currentFilter !== 'all') {
    items = items.filter(a => a.category === currentFilter);
  }

  if (currentSearch) {
    const q = currentSearch.toLowerCase();
    items = items.filter(a =>
      a.name.toLowerCase().includes(q) ||
      a.owner.toLowerCase().includes(q) ||
      a.desc.toLowerCase().includes(q) ||
      a.path.toLowerCase().includes(q)
    );
  }

  // Sort: by category order, then by name
  const catOrder = { tools: 0, findings: 1, data: 2, challenges: 3, builds: 4 };
  items.sort((a, b) => {
    const ca = catOrder[a.category] ?? 99;
    const cb = catOrder[b.category] ?? 99;
    if (ca !== cb) return ca - cb;
    return a.name.localeCompare(b.name);
  });

  return items;
}

function renderArtifacts() {
  const grid = document.getElementById('artifactGrid');
  const info = document.getElementById('resultsInfo');
  const items = getFilteredArtifacts();

  info.textContent = `Showing ${items.length} of ${INDEX_DATA.total} artifacts`;

  if (items.length === 0) {
    grid.innerHTML = `
      <div class="no-results" style="grid-column:1/-1">
        <div class="no-results-icon">🤔</div>
        <div>No artifacts match your search.</div>
      </div>
    `;
    return;
  }

  grid.innerHTML = items.slice(0, 200).map(a => `
    <div class="artifact-card" onclick="navigateTo('${a.path}')">
      <div class="artifact-header">
        <span class="artifact-cat cat-${a.category}">${a.category}</span>
        <span class="artifact-owner">${a.owner}</span>
      </div>
      <div class="artifact-name">${highlight(a.name, currentSearch)}</div>
      <div class="artifact-desc">${highlight(a.desc || '(no description)', currentSearch)}</div>
      <div class="artifact-footer">
        <span>${formatSize(a.size)}</span>
        <span>${a.path.split('/').length - 2} deep</span>
      </div>
    </div>
  `).join('');

  if (items.length > 200) {
    grid.innerHTML += `
      <div style="grid-column:1/-1;text-align:center;color:#6b7280;font-size:12px;padding:12px">
        Showing first 200 results. Refine your search to see more.
      </div>
    `;
  }
}

function formatSize(bytes) {
  if (bytes < 1024) return bytes + ' B';
  if (bytes < 1024 * 1024) return (bytes / 1024).toFixed(1) + ' KB';
  return (bytes / (1024 * 1024)).toFixed(1) + ' MB';
}

function navigateTo(path) {
  // Try to open the file - works if served from a web server
  window.open(path, '_blank');
}

init();
</script>
</body>
</html>
