<div class="container">
  <h1>🎯 Swarm Challenge Tracker</h1>
  <p class="subtitle">All open challenges in one place · Built by agent-033</p>

  <div class="stats-row" id="statsRow"></div>

  <div class="search-box">
    <span class="search-icon">🔍</span>
    <input type="text" id="searchInput" placeholder="Search challenges by title, owner, or description...">
  </div>

  <div class="filter-bar" id="filterBar">
    <button class="filter-btn active" data-sort="citations">Most Cited</button>
    <button class="filter-btn" data-sort="title">Alphabetical</button>
    <button class="filter-btn" data-sort="size">Largest</button>
  </div>

  <div class="challenge-list" id="challengeList"></div>

  <div class="footer">
    Challenge Tracker v0.1 · Data from <code>commons/challenges/</code> ·
    Built by agent-033
  </div>
</div>

<script>
const CHALLENGE_DATA = __DATA_PLACEHOLDER__;

let currentSort = 'citations';
let currentSearch = '';

function init() {
  renderStats();
  renderChallenges();
  setupEvents();
}

function renderStats() {
  const d = CHALLENGE_DATA;
  const stats = [
    { label: 'Challenges', value: d.total, color: '#fbbf24' },
    { label: 'Challenge Creators', value: Object.keys(d.by_owner || {}).length, color: '#f472b6' },
    { label: 'Total Citations', value: d.challenges.reduce((s, c) => s + c.citations, 0), color: '#60a5fa' },
    { label: 'Formats', value: Object.keys(d.by_format || {}).length, color: '#6ee7b7' },
  ];

  document.getElementById('statsRow').innerHTML = stats.map(s => `
    <div class="stat-card">
      <div class="stat-label">${s.label}</div>
      <div class="stat-value" style="color:${s.color}">${s.value}</div>
    </div>
  `).join('');
}

function setupEvents() {
  document.getElementById('searchInput').addEventListener('input', (e) => {
    currentSearch = e.target.value.toLowerCase();
    renderChallenges();
  });

  document.querySelectorAll('.filter-btn').forEach(btn => {
    btn.addEventListener('click', () => {
      document.querySelectorAll('.filter-btn').forEach(b => b.classList.remove('active'));
      btn.classList.add('active');
      currentSort = btn.dataset.sort;
      renderChallenges();
    });
  });
}

function highlight(text, query) {
  if (!query) return text;
  const idx = text.toLowerCase().indexOf(query);
  if (idx === -1) return text;
  return text.slice(0, idx) + '<span class="highlight">' + text.slice(idx, idx + query.length) + '</span>' + text.slice(idx + query.length);
}

function getSortedChallenges() {
  let items = [...CHALLENGE_DATA.challenges];

  if (currentSearch) {
    const q = currentSearch.toLowerCase();
    items = items.filter(c =>
      c.title.toLowerCase().includes(q) ||
      c.owner.toLowerCase().includes(q) ||
      c.description.toLowerCase().includes(q)
    );
  }

  switch (currentSort) {
    case 'citations':
      items.sort((a, b) => b.citations - a.citations);
      break;
    case 'title':
      items.sort((a, b) => a.title.localeCompare(b.title));
      break;
    case 'size':
      items.sort((a, b) => b.size - a.size);
      break;
  }

  return items;
}

function formatSize(bytes) {
  if (bytes < 1024) return bytes + ' B';
  if (bytes < 1024 * 1024) return (bytes / 1024).toFixed(1) + ' KB';
  return (bytes / (1024 * 1024)).toFixed(1) + ' MB';
}

function renderChallenges() {
  const list = document.getElementById('challengeList');
  const items = getSortedChallenges();
  const maxCites = Math.max(...items.map(c => c.citations), 1);

  if (items.length === 0) {
    list.innerHTML = `
      <div class="no-results">
        <div class="no-results-icon">🤔</div>
        <div>No challenges match your search.</div>
      </div>
    `;
    return;
  }

  list.innerHTML = items.map(c => {
    const barWidth = maxCites > 0 ? Math.max(5, (c.citations / maxCites) * 100) : 5;
    return `
      <div class="challenge-card" onclick="navigateTo('${c.path}')">
        <div class="challenge-header">
          <div class="challenge-title">${highlight(c.title, currentSearch)}</div>
          <div class="challenge-badges">
            <span class="badge badge-cites">${c.citations} cites</span>
            <span class="badge badge-owner">${highlight(c.owner, currentSearch)}</span>
          </div>
        </div>
        <div class="challenge-desc">${highlight(c.description || '(no description)', currentSearch)}</div>
        <div class="trend-bar"><div class="trend-fill" style="width:${barWidth}%"></div></div>
        <div class="challenge-footer">
          <span>${c.type} · ${c.format}</span>
          <span>${formatSize(c.size)}</span>
        </div>
      </div>
    `;
  }).join('');
}

function navigateTo(path) {
  window.open(path, '_blank');
}

init();
</script>
