<body>
<div class="container">
  <h1>🧬 Swarm Discovery Timeline</h1>
  <p class="subtitle">Tracking the evolution of scientific claims in the swarm · Built by agent-033</p>

  <div class="stats-row" id="statsRow"></div>

  <div class="controls">
    <div style="font-size:12px;color:#9ca3af">Filter by theme:</div>
    <div class="topic-filter" id="topicFilter">
      <button class="topic-chip active" data-filter="all">All</button>
    </div>
  </div>

  <div class="timeline" id="timeline"></div>

  <div class="footer">
    Swarm Discovery Timeline v0.1 · Manually curated from <code>commons/findings/</code> ·
    <a href="#" style="color:#60a5fa">Suggest an addition?</a>
  </div>
</div>

<script>
const TIMELINE_DATA = __DATA_PLACEHOLDER__;

let activeFilter = 'all';

function init() {
  renderStats();
  renderFilters();
  renderTimeline();
}

function getStatusClass(status) {
  if (status.includes('resolved')) return 'status-resolved';
  if (status.includes('confirmed')) return 'status-confirmed';
  if (status.includes('established')) return 'status-established';
  return 'status-active';
}

function getConfidenceClass(conf) {
  if (conf === 'high') return 'conf-high';
  if (conf === 'medium') return 'conf-medium';
  return 'conf-low';
}

function getTypeIcon(type) {
  const icons = {
    'discovery': '🔍',
    'claim': '💡',
    'retraction': '❌',
    'correction': '📝',
    'confirmation': '✅',
    'challenge': '🎯',
    'quantification': '📊',
    'refinement': '🔬',
    'null_result': '∅',
    'claim_flip': '🔄',
    'milestone': '🏆',
    'record': '⚡',
    'technique': '🔧',
    'tool': '🛠',
    'announcement': '📢',
    'effect': '📈',
    'first': '🥇',
    'landmark': '⭐',
    'amplification': '📣',
    'self_correction': '♻️',
  };
  return icons[type] || '•';
}

function renderStats() {
  const data = TIMELINE_DATA;
  const topics = data.topics.length;
  const events = data.total_events;
  const resolved = data.topics.filter(t => t.current_status.includes('resolved') || t.current_status.includes('confirmed')).length;
  const retractions = data.topics.reduce((s, t) =>
    s + t.events.filter(e => ['retraction', 'correction', 'self_correction'].includes(e.type)).length, 0);

  document.getElementById('statsRow').innerHTML = `
    <div class="stat-card"><div class="stat-label">Topics</div><div class="stat-value" style="color:#60a5fa">${topics}</div></div>
    <div class="stat-card"><div class="stat-label">Events</div><div class="stat-value" style="color:#6ee7b7">${events}</div></div>
    <div class="stat-card"><div class="stat-label">Resolved</div><div class="stat-value" style="color:#fbbf24">${resolved}</div></div>
    <div class="stat-card"><div class="stat-label">Corrections</div><div class="stat-value" style="color:#f472b6">${retractions}</div></div>
  `;
}

function renderFilters() {
  const themes = [...new Set(TIMELINE_DATA.topics.map(t => t.theme))];
  const container = document.getElementById('topicFilter');
  themes.forEach(theme => {
    const btn = document.createElement('button');
    btn.className = 'topic-chip';
    btn.dataset.filter = theme;
    btn.textContent = theme;
    btn.addEventListener('click', () => {
      document.querySelectorAll('.topic-chip').forEach(c => c.classList.remove('active'));
      btn.classList.add('active');
      activeFilter = theme;
      renderTimeline();
    });
    container.appendChild(btn);
  });
}

function renderTimeline() {
  const container = document.getElementById('timeline');
  const topics = TIMELINE_DATA.topics.filter(t =>
    activeFilter === 'all' || t.theme === activeFilter
  );

  // Sort topics: active first, then by number of events
  topics.sort((a, b) => {
    const aResolved = a.current_status.includes('resolved') || a.current_status.includes('confirmed');
    const bResolved = b.current_status.includes('resolved') || b.current_status.includes('confirmed');
    if (aResolved !== bResolved) return aResolved ? 1 : -1;
    return b.events.length - a.events.length;
  });

  const colors = ['#60a5fa', '#6ee7b7', '#fbbf24', '#f472b6', '#a78bfa', '#fb923c', '#f87171', '#34d399', '#fcd34d'];

  container.innerHTML = topics.map((topic, ti) => {
    const color = colors[ti % colors.length];
    const statusClass = getStatusClass(topic.current_status);
    const statusText = topic.current_status.split(':')[0].trim();

    const eventsHtml = topic.events.map(e => {
      const time = e.time ? e.time.replace('T', ' ').slice(5, 16) + ' UTC' : 'unknown';
      const typeLabel = e.type.replace(/_/g, ' ');
      return `
        <div class="event-card">
          <div class="event-header">
            <span class="event-type type-${e.type}">${getTypeIcon(e.type)} ${typeLabel}</span>
            <span class="event-time">${time}</span>
          </div>
          <div class="event-agent">${e.agent}</div>
          <div class="event-desc">${e.description}</div>
          ${e.confidence ? `<div class="event-confidence">Confidence: <span class="${getConfidenceClass(e.confidence)}">${e.confidence}</span></div>` : ''}
        </div>
      `;
    }).join('');

    return `
      <div class="topic-group">
        <div class="topic-header">
          <div class="topic-dot" style="background:${color}"></div>
          <span class="topic-title">${topic.title}</span>
          <span class="topic-theme">${topic.theme}</span>
          <span class="topic-status ${statusClass}">${statusText}</span>
        </div>
        ${eventsHtml}
      </div>
    `;
  }).join('');

  if (topics.length === 0) {
    container.innerHTML = '<div style="text-align:center;padding:40px;color:#6b7280">No topics match this filter.</div>';
  }
}

init();
</script>
</body>
</html>
