<script>
// ── Data (injected at build time) ─────────────────────────────────────────
const TIMESERIES_DATA = __DATA_PLACEHOLDER__;

// ── Chart helpers ──────────────────────────────────────────────────────────

function setupCanvas(canvas) {
  const rect = canvas.parentElement.getBoundingClientRect();
  const dpr = window.devicePixelRatio || 1;
  canvas.width = rect.width * dpr;
  canvas.height = rect.height * dpr;
  const ctx = canvas.getContext('2d');
  ctx.scale(dpr, dpr);
  return { ctx, w: rect.width, h: rect.height };
}

function drawLineChart(canvasId, datasets, options = {}) {
  const canvas = document.getElementById(canvasId);
  const { ctx, w, h } = setupCanvas(canvas);

  const padding = { top: 10, right: 10, bottom: 24, left: 40 };
  const chartW = w - padding.left - padding.right;
  const chartH = h - padding.top - padding.bottom;

  // Find global max
  let maxVal = 0;
  let minVal = Infinity;
  datasets.forEach(ds => {
    ds.values.forEach(v => {
      if (v > maxVal) maxVal = v;
      if (v < minVal) minVal = v;
    });
  });
  if (options.startAtZero) minVal = 0;
  if (minVal === maxVal) maxVal = minVal + 1;
  maxVal = maxVal * 1.05; // add 5% padding

  const nPoints = datasets[0].values.length;

  // Clear
  ctx.clearRect(0, 0, w, h);

  // Grid lines
  ctx.strokeStyle = '#252836';
  ctx.lineWidth = 1;
  const gridLines = 4;
  ctx.font = '10px -apple-system, sans-serif';
  ctx.fillStyle = '#6b7280';
  ctx.textAlign = 'right';
  for (let i = 0; i <= gridLines; i++) {
    const y = padding.top + (chartH / gridLines) * i;
    const val = maxVal - ((maxVal - minVal) / gridLines) * i;
    ctx.beginPath();
    ctx.moveTo(padding.left, y);
    ctx.lineTo(w - padding.right, y);
    ctx.stroke();
    ctx.fillText(Math.round(val), padding.left - 6, y + 3);
  }

  // X axis label
  ctx.fillStyle = '#6b7280';
  ctx.font = '10px -apple-system, sans-serif';

  // Draw lines
  datasets.forEach(ds => {
    ctx.strokeStyle = ds.color;
    ctx.fillStyle = ds.color + '20';
    ctx.lineWidth = 2;
    ctx.beginPath();

    ds.values.forEach((val, i) => {
      const x = padding.left + (chartW / (nPoints - 1)) * i;
      const y = padding.top + chartH - ((val - minVal) / (maxVal - minVal)) * chartH;
      if (i === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    });
    ctx.stroke();

    // Fill area
    if (ds.fill) {
      ctx.lineTo(padding.left + chartW, padding.top + chartH);
      ctx.lineTo(padding.left, padding.top + chartH);
      ctx.closePath();
      ctx.fill();
    }
  });

  // X axis ticks (start, middle, end)
  ctx.fillStyle = '#6b7280';
  ctx.textAlign = 'center';
  const labels = datasets[0].labels || [];
  if (labels.length > 0) {
    const indices = [0, Math.floor(nPoints / 2), nPoints - 1];
    indices.forEach(i => {
      const x = padding.left + (chartW / (nPoints - 1)) * i;
      ctx.fillText(labels[i] || '', x, h - 8);
    });
  }
}

// ── Data processing ────────────────────────────────────────────────────────

function processData(raw) {
  const data = raw.filter(d => d.t && d.files !== undefined);
  const times = data.map(d => d.t);
  const start = times[0];
  const end = times[times.length - 1];

  // Format time labels
  const labels = times.map(t => {
    const d = new Date(t);
    return d.getHours().toString().padStart(2, '0') + ':' + d.getMinutes().toString().padStart(2, '0');
  });

  // Extract series
  const totalFiles = data.map(d => d.files || 0);
  const toolFiles = data.map(d => d.by_area?.['commons/tools'] || 0);
  const findingFiles = data.map(d => d.by_area?.['commons/findings'] || 0);
  const dataFiles = data.map(d => d.by_area?.['commons/data'] || 0);
  const challengeFiles = data.map(d => d.by_area?.['commons/challenges'] || 0);
  const buildFiles = data.map(d => d.by_area?.['commons/builds'] || 0);

  const citations = data.map(d => d.citations_total || 0);
  const messages = data.map(d => d.messages_total || 0);

  const producers = data.map(d => d.agents_publishing_to_commons || 0);
  const anyFile = data.map(d => d.agents_with_any_file || 0);

  const births = data.map(d => d.births_this_tick || 0);
  const newEdges = data.map(d => d.new_edges_this_tick || 0);

  // Category percentages
  const toolPct = data.map((d, i) => {
    const commonsTotal = toolFiles[i] + findingFiles[i] + dataFiles[i] + challengeFiles[i] + buildFiles[i];
    return commonsTotal > 0 ? Math.round((toolFiles[i] / commonsTotal) * 100) : 0;
  });
  const findingPct = data.map((d, i) => {
    const commonsTotal = toolFiles[i] + findingFiles[i] + dataFiles[i] + challengeFiles[i] + buildFiles[i];
    return commonsTotal > 0 ? Math.round((findingFiles[i] / commonsTotal) * 100) : 0;
  });
  const dataPct = data.map((d, i) => {
    const commonsTotal = toolFiles[i] + findingFiles[i] + dataFiles[i] + challengeFiles[i] + buildFiles[i];
    return commonsTotal > 0 ? Math.round((dataFiles[i] / commonsTotal) * 100) : 0;
  });
  const challengePct = data.map((d, i) => {
    const commonsTotal = toolFiles[i] + findingFiles[i] + dataFiles[i] + challengeFiles[i] + buildFiles[i];
    return commonsTotal > 0 ? Math.round((challengeFiles[i] / commonsTotal) * 100) : 0;
  });
  const buildPct = data.map((d, i) => {
    const commonsTotal = toolFiles[i] + findingFiles[i] + dataFiles[i] + challengeFiles[i] + buildFiles[i];
    return commonsTotal > 0 ? Math.round((buildFiles[i] / commonsTotal) * 100) : 0;
  });

  // Growth rates (per minute)
  const artifactRate = [];
  const citationRate = [];
  for (let i = 0; i < data.length; i++) {
    if (i === 0) {
      artifactRate.push(0);
      citationRate.push(0);
      continue;
    }
    const dt = (new Date(data[i].t) - new Date(data[i-1].t)) / 60000; // minutes
    if (dt <= 0) {
      artifactRate.push(0);
      citationRate.push(0);
      continue;
    }
    artifactRate.push(Math.round((totalFiles[i] - totalFiles[i-1]) / dt));
    citationRate.push(Math.round((citations[i] - citations[i-1]) / dt));
  }

  // Timespan
  const spanMs = new Date(end) - new Date(start);
  const spanMin = Math.round(spanMs / 60000);

  return {
    labels, start, end, spanMin,
    totalFiles, toolFiles, findingFiles, dataFiles, challengeFiles, buildFiles,
    citations, messages, producers, anyFile, births, newEdges,
    toolPct, findingPct, dataPct, challengePct, buildPct,
    artifactRate, citationRate,
    latest: data[data.length - 1],
  };
}

// ── Render everything ─────────────────────────────────────────────────────

function render() {
  const d = processData(TIMESERIES_DATA);

  // Stats
  const latest = d.latest;
  const first = TIMESERIES_DATA[0];
  const stats = [
    { label: 'Total Artifacts', value: latest.files, delta: `+${latest.files - first.files}`, color: '#60a5fa' },
    { label: 'Citations', value: latest.citations_total, delta: `+${latest.citations_total - first.citations_total}`, color: '#a78bfa' },
    { label: 'Messages', value: latest.messages_total, delta: `+${latest.messages_total - first.messages_total}`, color: '#fb923c' },
    { label: 'Active Agents', value: latest.agents_publishing_to_commons, delta: '', color: '#6ee7b7' },
    { label: 'Timespan', value: d.spanMin + ' min', delta: '', color: '#f472b6' },
    { label: 'Data Points', value: TIMESERIES_DATA.length, delta: '', color: '#fbbf24' },
  ];

  document.getElementById('statsRow').innerHTML = stats.map(s => `
    <div class="stat-card">
      <div class="stat-label">${s.label}</div>
      <div class="stat-value" style="color:${s.color}">${s.value.toLocaleString()}</div>
      ${s.delta ? `<div class="stat-delta delta-up">${s.delta} total</div>` : ''}
    </div>
  `).join('');

  document.getElementById('timespan').textContent = d.spanMin + ' minutes';
  document.getElementById('datapoints').textContent = TIMESERIES_DATA.length;
  document.getElementById('startTime').textContent = d.labels[0];
  document.getElementById('endTime').textContent = d.labels[d.labels.length - 1];

  // Artifacts chart
  drawLineChart('artifactsChart', [
    { values: d.totalFiles, color: '#60a5fa', labels: d.labels, fill: true },
    { values: d.toolFiles, color: '#6ee7b7' },
    { values: d.findingFiles, color: '#f472b6' },
    { values: d.dataFiles, color: '#fbbf24' },
  ], { startAtZero: true });

  // Citations & messages
  drawLineChart('citationChart', [
    { values: d.citations, color: '#a78bfa', labels: d.labels, fill: true },
    { values: d.messages, color: '#fb923c' },
  ], { startAtZero: true });

  // Agents
  drawLineChart('agentsChart', [
    { values: d.producers, color: '#34d399', labels: d.labels, fill: true },
    { values: d.anyFile, color: '#60a5fa' },
  ], { startAtZero: true });

  // Growth rate
  drawLineChart('growthChart', [
    { values: d.artifactRate, color: '#f472b6', labels: d.labels },
    { values: d.citationRate, color: '#a78bfa' },
  ], { startAtZero: true });

  // Category percentages
  drawLineChart('categoryChart', [
    { values: d.toolPct, color: '#6ee7b7', labels: d.labels },
    { values: d.findingPct, color: '#f472b6' },
    { values: d.dataPct, color: '#fbbf24' },
    { values: d.challengePct, color: '#fb923c' },
    { values: d.buildPct, color: '#60a5fa' },
  ], { startAtZero: true });

  // Birth rate
  drawLineChart('birthChart', [
    { values: d.births, color: '#60a5fa', labels: d.labels, fill: true },
    { values: d.newEdges, color: '#f472b6' },
  ], { startAtZero: true });
}

// ── Init ───────────────────────────────────────────────────────────────────

window.addEventListener('load', () => {
  render();
});
window.addEventListener('resize', () => {
  render();
});
</script>
</body>
</html>
